fn is_assignment_word(word: &str) -> bool {
    if let Some(eq_pos) = word.find('=') {
        if eq_pos == 0 {
            return false;
        }
        let left = &word[..eq_pos];
        // Remove array index like arr[0]
        let left_base = if let Some(bracket) = left.find('[') {
            &left[..bracket]
        } else {
            left
        };
        if left_base.is_empty() {
            return false;
        }
        let mut chars = left_base.chars();
        let first = chars.next().unwrap();
        if !(first.is_alphabetic() || first == '_') {
            return false;
        }
        for c in chars {
            if !(c.is_alphanumeric() || c == '_') {
                return false;
            }
        }
        return true;
    }
    false
}

