use std::fs;
use std::io::{self, Read};
use std::path::Path;
use std::process;

const VERSION: &str = "4.3.1";
const HELP_TEXT: &str = "Shellharden: The corrective bash syntax highlighter.\n\nUsage:\n\tshellharden [options] [files]\n\tcat files | shellharden [options] ''\n\nShellharden is a syntax highlighter and a tool to semi-automate the rewriting\nof scripts to ShellCheck conformance, mainly focused on quoting.\n\nThe default mode of operation is like `cat`, but with syntax highlighting in\nforeground colors and suggestive changes in background colors.\n\nOptions:\n\t--suggest         Output a colored diff suggesting changes.\n\t--syntax          Output syntax highlighting with ANSI colors.\n\t--syntax-suggest  Diff with syntax highlighting (default mode).\n\t--transform       Output suggested changes.\n\t--check           No output; exit with 2 if changes are suggested.\n\t--replace         Replace file contents with suggested changes.\n\t--                Don't treat further arguments as options.\n\t-h|--help         Show help text.\n\t--version         Show version.\n\nThe changes suggested by Shellharden inhibits word splitting and indirect\npathname expansion. This will make your script ShellCheck compliant in terms of\nquoting. Whether your script will work afterwards is a different question:\nIf your script was using those features on purpose, it obviously won't anymore!\n\nEvery script is possible to write without using word splitting or indirect\npathname expansion, but it may involve doing things differently.\nSee the accompanying file how_to_do_things_safely_in_bash.md or online:\nhttps://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md\n";

#[derive(Debug, Clone, PartialEq)]
enum Mode {
    Suggest,
    Syntax,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

fn parse_args(args: &[String]) -> (Vec<String>, Option<Mode>, Vec<String>, Option<String>) {
    // Returns (help_version_seq, mode, files, unknown_opt)
    // help_version_seq is in order encountered
    let mut help_version_seq = Vec::new();
    let mut mode: Option<Mode> = None;
    let mut files = Vec::new();
    let mut unknown_opt: Option<String> = None;
    let mut dashdash = false;
    let mut dashdash_seen = false;
    // First, find -- index
    let mut dashdash_idx: Option<usize> = None;
    for (idx, arg) in args.iter().enumerate() {
        if arg == "--" {
            dashdash_idx = Some(idx);
            break;
        }
    }
    let (to_parse, trailing) = if let Some(idx) = dashdash_idx {
        (&args[..idx], Some(&args[idx+1..]))
    } else {
        (args, None)
    };
    for arg in to_parse {
        if dashdash {
            // Should not happen because we split, but if to_parse contains --, it would be first, so no
            files.push(arg.clone());
            continue;
        }
        if arg == "--suggest" {
            mode = Some(Mode::Suggest);
        } else if arg == "--syntax" {
            mode = Some(Mode::Syntax);
        } else if arg == "--syntax-suggest" {
            mode = Some(Mode::SyntaxSuggest);
        } else if arg == "--transform" {
            mode = Some(Mode::Transform);
        } else if arg == "--check" {
            mode = Some(Mode::Check);
        } else if arg == "--replace" {
            mode = Some(Mode::Replace);
        } else if arg == "--help" || arg == "-h" {
            help_version_seq.push("help".to_string());
        } else if arg == "--version" {
            help_version_seq.push("version".to_string());
        } else if arg == "--" {
            dashdash = true;
        } else if arg.starts_with('-') {
            unknown_opt = Some(arg.clone());
            break;
        } else {
            files.push(arg.clone());
        }
    }
    if let Some(t) = trailing {
        for arg in t {
            files.push(arg.clone());
        }
    }
    (help_version_seq, mode, files, unknown_opt)
}

fn is_var_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}
fn is_var_start(c: char) -> bool {
    c.is_alphabetic() || c == '_'
}

// Simple transform: we will implement a state machine that handles many observed cases
// For now, we will implement a function that transforms a single line's code part
fn transform_text(text: &str) -> String {
    // Handle heredoc and line splitting
    let mut out = String::new();
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    // Actually split_inclusive keeps delimiter
    let mut in_heredoc = false;
    let mut heredoc_delim = String::new();
    let mut heredoc_strip = false;
    for line in lines {
        // Check if in heredoc
        if in_heredoc {
            out.push_str(line);
            // Check if line is delimiter
            let stripped = line.trim_end_matches(|c| c == '\n' || c == '\r');
            let check = if heredoc_strip {
                stripped.trim_start_matches('\t')
            } else {
                stripped
            };
            if check == heredoc_delim {
                in_heredoc = false;
                heredoc_delim.clear();
                heredoc_strip = false;
            }
            continue;
        }
        // Check for heredoc start in line (outside quotes)
        // Simple regex search for <<[-]? and delimiter
        // We will search for << pattern not in quotes (approx)
        // For now, use simple search for "<<"
        if line.contains("<<") && !line.contains("<<<") {
            // Use regex-like find
            // Find << occurrence that is not inside single/double quotes
            // For simplicity, find first << not in quotes
            let mut in_single = false;
            let mut in_double = false;
            let mut found = None;
            let chars: Vec<char> = line.chars().collect();
            let mut i = 0;
            while i + 1 < chars.len() {
                let c = chars[i];
                if c == '\'' && !in_double {
                    in_single = !in_single;
                } else if c == '"' && !in_single {
                    // handle escapes?
                    if i > 0 && chars[i-1] == '\\' {
                    } else {
                        in_double = !in_double;
                    }
                }
                if !in_single && !in_double && chars[i] == '<' && chars[i+1] == '<' {
                    // Check for <<<
                    if i+2 < chars.len() && chars[i+2] == '<' {
                        i += 3;
                        continue;
                    }
                    // Found heredoc start
                    // Parse delimiter after <<
                    let mut j = i+2;
                    // Check for '-'
                    let mut strip = false;
                    if j < chars.len() && chars[j] == '-' {
                        strip = true;
                        j += 1;
                    }
                    // Skip whitespace
                    while j < chars.len() && chars[j].is_whitespace() && chars[j] != '\n' {
                        j += 1;
                    }
                    // Check for quoted delimiter
                    let mut delim = String::new();
                    let mut quoted = false;
                    let mut quote_char = '\0';
                    if j < chars.len() && (chars[j] == '\'' || chars[j] == '"' || chars[j] == '\\') {
                        if chars[j] == '\'' || chars[j] == '"' {
                            quoted = true;
                            quote_char = chars[j];
                            j += 1;
                            while j < chars.len() && chars[j] != quote_char && chars[j] != '\n' {
                                delim.push(chars[j]);
                                j += 1;
                            }
                            if j < chars.len() && chars[j] == quote_char {
                                j += 1;
                            }
                        } else if chars[j] == '\\' {
                            // escaped char
                            j += 1;
                            if j < chars.len() && !chars[j].is_whitespace() {
                                delim.push(chars[j]);
                                j += 1;
                            }
                        }
                    } else {
                        while j < chars.len() && !chars[j].is_whitespace() && chars[j] != '\n' && chars[j] != '|' && chars[j] != ';' && chars[j] != '&' {
                            delim.push(chars[j]);
                            j += 1;
                        }
                    }
                    if !delim.is_empty() {
                        found = Some((delim.clone(), strip));
                        break;
                    }
                }
                i += 1;
            }
            // Transform line first, then set heredoc
            let transformed = transform_line(line);
            out.push_str(&transformed);
            if let Some((delim, strip)) = found {
                in_heredoc = true;
                heredoc_delim = delim;
                heredoc_strip = strip;
            }
            continue;
        }
        out.push_str(&transform_line(line));
    }
    out
}

fn transform_line(line: &str) -> String {
    // Preserve newline
    let (content, newline) = if line.ends_with("\r\n") {
        (&line[..line.len()-2], "\r\n")
    } else if line.ends_with('\n') || line.ends_with('\r') {
        (&line[..line.len()-1], &line[line.len()-1..])
    } else {
        (line, "")
    };
    // Find comment start outside quotes
    let comment_start = find_comment_start(content);
    let (code, comment) = if let Some(pos) = comment_start {
        (&content[..pos], &content[pos..])
    } else {
        (content, "")
    };
    let transformed_code = transform_code(code);
    format!("{}{}{}", transformed_code, comment, newline)
}

fn find_comment_start(s: &str) -> Option<usize> {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let chars: Vec<char> = s.chars().collect();
    for i in 0..chars.len() {
        let c = chars[i];
        if escaped {
            escaped = false;
            continue;
        }
        if c == '\\' && !in_single {
            escaped = true;
            continue;
        }
        if c == '\'' && !in_double {
            in_single = !in_single;
            continue;
        }
        if c == '"' && !in_single {
            // check if escaped
            if i > 0 && chars[i-1] == '\\' {
                continue;
            }
            in_double = !in_double;
            continue;
        }
        if c == '#' && !in_single && !in_double {
            if i == 0 || chars[i-1].is_whitespace() || chars[i-1] == ';' || chars[i-1] == '|' || chars[i-1] == '&' || chars[i-1] == '(' {
                // require whitespace before # for comment, or at start, or after ;|& etc.
                // Actually earlier we saw echo $var#notcomment not comment, so require whitespace before #
                if i == 0 || chars[i-1].is_whitespace() {
                    return Some(s.chars().take(i).collect::<String>().len());
                }
                // Also after ; without space, treat as comment? Let's check: ";#"
                // For simplicity, treat as comment if previous char is ;|& etc. even without space
                if chars[i-1] == ';' || chars[i-1] == '|' || chars[i-1] == '&' || chars[i-1] == '(' {
                    return Some(s.chars().take(i).collect::<String>().len());
                }
            }
        }
    }
    None
}

fn transform_code(code: &str) -> String {
    // Tokenize and transform words
    // For simplicity, we will implement a scanner that directly handles expansions
    // This is a simplified placeholder that handles basic cases
    // We will handle:
    // - backticks -> $()
    // - $*, $@ -> "$@"
    // - $var, ${var}, etc.
    // - $(cmd) outer quoting
    // - comments already stripped
    // For state, we handle in_single, in_double, etc.
    // For assignment suppression, we will handle by detecting assignment words
    // For for/select, case, [[, (( suppression, we will handle via flags

    // First, convert backticks to $()
    let code = convert_backticks(code);
    // Now scan code and transform expansions
    // We'll implement word-level transform with context
    // For simplicity, split by preserving whitespace and operators, then transform each word
    let tokens = tokenize(code.as_str());
    let mut out = String::new();
    let mut at_command_start = true;
    // Need to track for/select state
    let mut expect_for_var = false;
    let mut expect_in = false;
    let mut in_for_in = false;
    let mut for_in_depth = 0;
    // Track bracket contexts
    let mut dbl_bracket_depth = 0;
    let mut dbl_paren_depth = 0;
    let mut last_was_for = false;
    let mut last_was_select = false;

    for (tok_type, tok_val) in tokens {
        match tok_type.as_str() {
            "word" => {
                // Determine if this word is a keyword that affects context
                let word = tok_val.as_str();
                // Check keywords
                if word == "for" {
                    out.push_str(word);
                    at_command_start = false;
                    expect_for_var = true;
                    last_was_for = true;
                    last_was_select = false;
                    continue;
                } else if word == "select" {
                    out.push_str(word);
                    at_command_start = false;
                    expect_for_var = true;
                    last_was_select = true;
                    last_was_for = false;
                    continue;
                } else if expect_for_var {
                    // This word is the loop variable
                    out.push_str(word);
                    expect_for_var = false;
                    expect_in = true;
                    at_command_start = false;
                    continue;
                } else if expect_in && word == "in" {
                    out.push_str(word);
                    expect_in = false;
                    in_for_in = true;
                    at_command_start = false;
                    continue;
                } else if in_for_in {
                    // This word is in for-in list until ; or do
                    // Check if word is "do" or ";" then exit for_in
                    if word == "do" || word == ";" {
                        out.push_str(word);
                        if word == "do" {
                            in_for_in = false;
                        }
                        at_command_start = true; // after ;, new command
                        continue;
                    } else if word == ";" {
                        out.push_str(word);
                        in_for_in = false;
                        at_command_start = true;
                        continue;
                    } else {
                        // This word is in list, transform with for_in flag
                        let transformed = transform_word(word, false, true);
                        out.push_str(&transformed);
                        at_command_start = false;
                        continue;
                    }
                }
                // Check for case
                if word == "case" {
                    out.push_str(word);
                    at_command_start = false;
                    // Next word is case word which should not be quoted, we will suppress next word
                    // For simplicity, we will set a flag to suppress next word
                    // We'll use a separate state
                    // Use expect_case_word
                    // For now, push and handle via flag
                    // We'll manage via a simple flag
                    // Instead, we will treat case word as not transformed
                    // We can set a one-shot flag
                    // Use global variable case_next
                    // For simplicity, we will handle by checking if previous token was case
                    // So we need to track case_pending
                    // We'll set case_pending = true
                    // Instead, we will handle with a flag outside loop
                    // For now, we will just push and let next word be suppressed via checking previous token
                    // We'll need to store state
                    // Let's use a flag
                    // We'll set a variable
                    // For simplicity, we will handle case word suppression by looking ahead: not needed for now
                    // We'll just transform as normal but case word should not be quoted, so we need to suppress
                    // We'll implement via a flag
                    // Because we are iterating, we can set a flag after "case"
                    // So set case_pending
                    // We'll do it after the match
                    // For now, just continue and handle after
                    // We'll need to manage case_pending flag outside
                    // Let's add flag
                    continue;
                }
                // For now, handle assignment detection
                let is_assignment = is_assignment_word(word) && at_command_start;
                // Also handle export/declare etc. assignments
                // For simplicity, we will handle assignment suppression for plain assignments
                // Also handle array assignments like a=($var) -> inner should be quoted even if assignment
                if is_assignment {
                    // Check if RHS starts with '('
                    if let Some(eq_pos) = word.find('=') {
                        let rhs = &word[eq_pos+1..];
                        if rhs.starts_with('(') {
                            // Array assignment: transform inner
                            let l = word.find('(').unwrap();
                            let r = word.rfind(')').unwrap_or(word.len()-1);
                            if r > l {
                                let inner = &word[l+1..r];
                                // inner may contain multiple words, transform each word inside
                                // For simplicity, split inner by whitespace and transform each
                                let inner_words: Vec<&str> = inner.split_whitespace().collect();
                                let mut transformed_inner = String::new();
                                for (idx, w) in inner_words.iter().enumerate() {
                                    if idx > 0 {
                                        transformed_inner.push(' ');
                                    }
                                    transformed_inner.push_str(&transform_word(w, false, false));
                                }
                                // Reconstruct with original spacing? Use single space
                                let reconstructed = format!("{}({}){}", &word[..l], transformed_inner, &word[r+1..]);
                                out.push_str(&reconstructed);
                            } else {
                                out.push_str(word);
                            }
                        } else {
                            // Simple assignment, do not quote
                            // But need to handle that RHS may contain $(...) inner which should be quoted
                            // For a=$(echo $var), the $var inside should be quoted
                            // So we need to transform inner expansions inside RHS even though outer not quoted
                            // For example, a=$(echo $var) -> a=$(echo "$var")
                            // So we need to transform RHS inner
                            // We'll find expansions inside RHS and quote them
                            let lhs = &word[..eq_pos+1];
                            let rhs = &word[eq_pos+1..];
                            let transformed_rhs = transform_inner_for_assignment(rhs);
                            out.push_str(lhs);
                            out.push_str(&transformed_rhs);
                        }
                    } else {
                        out.push_str(word);
                    }
                    // After assignment, stay at command start (since assignments can chain)
                    // So at_command_start remains true until non-assignment word
                    // But we already have at_command_start true, keep it
                    continue;
                }
                // Check for dbl bracket or dbl paren suppression
                // For now, we will handle [[ and (( by not quoting inside
                // Detect if we are inside [[ ]]
                // For simplicity, we will track depth based on previous tokens
                // If we are inside [[ ... ]], we should not quote
                // We can track by seeing tokens that are "[[" and "]]"
                // But our tokenization splits "[[" as two "["? Need to handle
                // For now, we will just transform as normal but with suppress if inside
                // We'll need to track state before transforming word
                // For simplicity, we will not handle [[ suppression for now, but we will handle it via scanning code for [[ and ]]
                // For now, just transform normally
                let transformed = transform_word(word, false, false);
                out.push_str(&transformed);
                at_command_start = false;
            },
            "op" => {
                out.push_str(&tok_val);
                // Operators that reset command start
                if tok_val == ";" || tok_val == "&&" || tok_val == "||" || tok_val == "|" || tok_val == "&" || tok_val == "(" || tok_val == "{" || tok_val == "then" || tok_val == "do" || tok_val == "else" || tok_val == "elif" || tok_val == "case" || tok_val == "while" || tok_val == "until" || tok_val == "for" || tok_val == "select" || tok_val == "if" {
                    at_command_start = true;
                    if in_for_in && (tok_val == ";" || tok_val == "do") {
                        if tok_val == "do" {
                            in_for_in = false;
                        } else if tok_val == ";" {
                            // stay in_for_in? Actually for i in a; do -> after ;, still in_for_in until do?
                            // For simplicity, keep in_for_in until do
                        }
                    }
                }
                // Handle [[ and ]] for suppression
                if tok_val == "[[" {
                    dbl_bracket_depth += 1;
                } else if tok_val == "]]" {
                    if dbl_bracket_depth > 0 {
                        dbl_bracket_depth -= 1;
                    }
                }
                if tok_val == "((" {
                    dbl_paren_depth += 1;
                } else if tok_val == "))" {
                    if dbl_paren_depth > 0 {
                        dbl_paren_depth -= 1;
                    }
                }
            },
            "space" => {
                out.push_str(&tok_val);
            },
            "other" => {
                out.push_str(&tok_val);
            },
            _ => {
                out.push_str(&tok_val);
            }
        }
    }
    out
}

fn is_assignment_word(word: &str) -> bool {
    if let Some(eq_pos) = word.find('=') {
        if eq_pos == 0 {
            return false;
        }
        let left = &word[..eq_pos];
        // Remove array index like arr[0]
        let left_base = if let Some(bracket) = left.find('[') {
            &left[..bracket]
        } else {
            left
        };
        if left_base.is_empty() {
            return false;
        }
        let mut chars = left_base.chars();
        let first = chars.next().unwrap();
        if !(first.is_alphabetic() || first == '_') {
            return false;
        }
        for c in chars {
            if !(c.is_alphanumeric() || c == '_') {
                return false;
            }
        }
        return true;
    }
    false
}

fn transform_inner_for_assignment(rhs: &str) -> String {
    // Transform RHS inner expansions like $(echo $var) -> $(echo "$var")
    // For now, handle $(...) and $(( )) etc.
    // We'll use transform_word on RHS as if it's a word, but need to handle that RHS may be like "$(echo $var)" or "foo $var bar"
    // For simplicity, we will transform RHS by scanning for $ expansions and quoting them, but not quoting simple $var directly (since assignment not quoted)
    // However, for RHS that is $(...), we want to quote inner
    // Example: rhs = "$(echo $var)" -> inner $var should be quoted inside $(...)
    // So we can just call transform_word on rhs with suppress false? But that would quote the whole rhs as '"$(echo "$var")"' which is not correct for assignment (should be '$(echo "$var")' without outer quotes? Actually a=$(echo $var) should become a=$(echo "$var") not a="$(echo "$var")" . So outer not quoted.
    // For assignment, we should not add outer quotes, but we should quote inner expansions inside command substitutions
    // So we need to handle this specially
    // For now, we will handle by finding $(...) patterns and transforming inner
    let mut out = String::new();
    let mut i = 0;
    let chars: Vec<char> = rhs.chars().collect();
    while i < chars.len() {
        if chars[i] == '$' && i+1 < chars.len() && chars[i+1] == '(' {
            // Find matching )
            if i+2 < chars.len() && chars[i+2] == '(' {
                // $(( - arithmetic, not transform
                // Find ))
                let mut j = i+3;
                let mut depth = 1;
                while j + 1 < chars.len() {
                    if chars[j] == '(' && chars[j+1] == '(' {
                        depth += 1;
                        j += 2;
                        continue;
                    }
                    if chars[j] == ')' && chars[j+1] == ')' {
                        depth -= 1;
                        if depth == 0 {
                            j += 2;
                            break;
                        }
                        j += 2;
                        continue;
                    }
                    j += 1;
                }
                out.push_str(&rhs[i..j]);
                i = j;
                continue;
            } else {
                // $(...)
                let mut depth = 1;
                let mut j = i+2;
                while j < chars.len() && depth > 0 {
                    if chars[j] == '(' {
                        depth += 1;
                    } else if chars[j] == ')' {
                        depth -= 1;
                        if depth == 0 {
                            j += 1;
                            break;
                        }
                    }
                    j += 1;
                }
                let inner = &rhs[i+2..j-1];
                let transformed_inner = transform_text(inner);
                out.push_str("$(");
                out.push_str(&transformed_inner);
                out.push_str(")");
                i = j;
                continue;
            }
        } else if chars[i] == '`' {
            // backtick
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' {
                j += 1;
            }
            if j < chars.len() && chars[j] == '`' {
                let inner = &rhs[i+1..j];
                let transformed_inner = transform_text(inner);
                out.push_str("$(");
                out.push_str(&transformed_inner);
                out.push_str(")");
                i = j+1;
                continue;
            } else {
                out.push(chars[i]);
                i += 1;
                continue;
            }
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

fn convert_backticks(s: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut in_single = false;
    let mut in_double = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' && !in_double {
            in_single = !in_single;
            out.push(c);
            i += 1;
            continue;
        }
        if c == '"' && !in_single {
            if i > 0 && chars[i-1] == '\\' {
                out.push(c);
                i += 1;
                continue;
            }
            in_double = !in_double;
            out.push(c);
            i += 1;
            continue;
        }
        if c == '`' && !in_single && !in_double {
            // Find closing `
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' {
                j += 1;
            }
            if j < chars.len() {
                let inner = &s[i+1..j];
                let transformed_inner = transform_text(inner);
                out.push_str("$(");
                out.push_str(&transformed_inner);
                out.push_str(")");
                i = j+1;
                continue;
            } else {
                out.push(c);
                i += 1;
                continue;
            }
        }
        out.push(c);
        i += 1;
    }
    out
}

fn transform_word(word: &str, suppress: bool, is_for_in: bool) -> String {
    // Handle expansions in word
    // For now, we will implement a scanner that handles quoting
    // This is a simplified version that handles merging
    // We will use the same logic as before but in Rust
    // For brevity, we will handle basic cases

    // Find expansions
    let exps = find_expansions(word);
    if exps.is_empty() {
        return word.to_string();
    }
    if suppress {
        // For suppressed, we still need to handle $() inner
        // For now, just return word as is but transform inner of $()
        let mut out = String::new();
        let mut last = 0;
        for exp in &exps {
            out.push_str(&word[last..exp.start]);
            let text = &word[exp.start..exp.end];
            if exp.typ == "cmdsub" {
                let inner = &text[2..text.len()-1];
                let transformed_inner = transform_text(inner);
                out.push_str("$(");
                out.push_str(&transformed_inner);
                out.push_str(")");
            } else if exp.typ == "backtick" {
                let inner = &text[1..text.len()-1];
                let transformed_inner = transform_text(inner);
                out.push_str("$(");
                out.push_str(&transformed_inner);
                out.push_str(")");
            } else {
                out.push_str(text);
            }
            last = exp.end;
        }
        out.push_str(&word[last..]);
        return out;
    }
    if is_for_in {
        if exps.len() == 1 && word.trim() == exps[0].text {
            let exp = &exps[0];
            match exp.typ.as_str() {
                "var" => {
                    let var = &exp.text[1..];
                    return format!("\"${{{}[@]}}\"", var);
                },
                "param_simple" => {
                    let var = exp.inner.as_ref().unwrap();
                    return format!("\"${{{}[@]}}\"", var);
                },
                "array" => {
                    let mut inner = exp.inner.as_ref().unwrap().clone();
                    if inner.ends_with("[*]") {
                        inner = inner[..inner.len()-3].to_string() + "[@]";
                    }
                    return format!("\"${{{}}}\"", inner);
                },
                "special" => {
                    if exp.text == "$*" || exp.text == "$@" {
                        return "\"$@\"".to_string();
                    } else {
                        return exp.text.clone();
                    }
                },
                "cmdsub" => {
                    let inner = &exp.text[2..exp.text.len()-1];
                    let transformed_inner = transform_text(inner);
                    return format!("\"$({})\"", transformed_inner);
                },
                _ => {
                    return format!("\"{}\"", exp.text);
                }
            }
        }
    }
    // Normal case
    // For single expansion
    if exps.len() == 1 {
        let exp = &exps[0];
        let prefix = &word[..exp.start];
        let suffix = &word[exp.end..];
        // Handle suffix that is double-quoted
        if suffix.starts_with('"') {
            if let Some(end_q) = suffix[1..].find('"') {
                let end_q = end_q + 1;
                let quoted_part = &suffix[..end_q+1];
                let rest = &suffix[end_q+1..];
                let inner_lit = &quoted_part[1..quoted_part.len()-1];
                match exp.typ.as_str() {
                    "var" => {
                        let var = &exp.text[1..];
                        return format!("{}{}\"{}", prefix, format!("\"${{{}}}{}\"", var, inner_lit), rest);
                    },
                    "param_simple" => {
                        let var = exp.inner.as_ref().unwrap();
                        return format!("{}{}\"{}", prefix, format!("\"${{{}}}{}\"", var, inner_lit), rest);
                    },
                    _ => {}
                }
            }
        }
        if suffix.starts_with('\'') && suffix.ends_with('\'') && suffix.len() >= 2 {
            // Single quoted, not merged
            match exp.typ.as_str() {
                "var" => {
                    let var = &exp.text[1..];
                    return format!("{}\"{}\"{}", prefix, format!("${}", var), suffix);
                },
                "param_simple" => {
                    let var = exp.inner.as_ref().unwrap();
                    return format!("{}\"{}\"{}", prefix, format!("${}", var), suffix);
                },
                _ => {}
            }
        }
        // Handle general single
        match exp.typ.as_str() {
            "var" => {
                let var = &exp.text[1..];
                if !suffix.is_empty() && (suffix.chars().next().unwrap().is_alphanumeric() || suffix.chars().next().unwrap() == '_') {
                    return format!("{}\"{}\"{}", prefix, format!("${{{}}}", var), suffix);
                } else {
                    return format!("{}\"{}\"{}", prefix, format!("${}", var), suffix);
                }
            },
            "param_simple" => {
                let var = exp.inner.as_ref().unwrap();
                if suffix.is_empty() {
                    return format!("{}\"{}\"{}", prefix, format!("${}", var), suffix);
                } else {
                    return format!("{}\"{}\"{}", prefix, format!("${{{}}}", var), suffix);
                }
            },
            "array" => {
                let mut inner = exp.inner.as_ref().unwrap().clone();
                if inner.ends_with("[*]") {
                    inner = inner[..inner.len()-3].to_string() + "[@]";
                }
                return format!("{}\"{}\"{}", prefix, format!("${{{}}}", inner), suffix);
            },
            "special" => {
                if exp.text == "$*" || exp.text == "$@" {
                    return format!("{}\"{}\"{}", prefix, "\"$@\"", suffix);
                } else {
                    return format!("{}{}{}", prefix, exp.text, suffix);
                }
            },
            "cmdsub" => {
                let inner = &exp.text[2..exp.text.len()-1];
                let transformed_inner = transform_text(inner);
                return format!("{}\"{}\"{}", prefix, format!("$({})", transformed_inner), suffix);
            },
            "param_complex" => {
                return format!("{}\"{}\"{}", prefix, exp.text, suffix);
            },
            "arith" => {
                return format!("{}{}{}", prefix, exp.text, suffix);
            },
            "old_arith" => {
                let inner = &exp.text[2..exp.text.len()-1];
                let transformed_inner = transform_text(inner);
                return format!("{}$[{}{}]{}", prefix, "", transformed_inner, suffix);
            },
            "backtick" => {
                let inner = &exp.text[1..exp.text.len()-1];
                let transformed_inner = transform_text(inner);
                return format!("{}\"{}\"{}", prefix, format!("$({})", transformed_inner), suffix);
            },
            _ => {
                return format!("{}\"{}\"{}", prefix, exp.text, suffix);
            }
        }
    }
    // Multiple expansions
    let first = &exps[0];
    let last = exps[exps.len()-1].clone();
    let prefix = &word[..first.start];
    let suffix = &word[last.end..];
    let middle = &word[first.start..last.end];
    let mut inner_parts: Vec<String> = Vec::new();
    let mut pos = 0;
    for exp in &exps {
        let exp_start_in_middle = exp.start - first.start;
        let exp_end_in_middle = exp.end - first.start;
        if pos < exp_start_in_middle {
            inner_parts.push(middle[pos..exp_start_in_middle].to_string());
        }
        match exp.typ.as_str() {
            "var" => {
                let var = &exp.text[1..];
                // Check next literal for braces
                let idx = exps.iter().position(|e| e.start == exp.start).unwrap();
                let mut need_brace = false;
                if idx + 1 < exps.len() {
                    let next_exp = &exps[idx+1];
                    let next_literal = &middle[exp_end_in_middle..next_exp.start - first.start];
                    if !next_literal.is_empty() {
                        if next_literal.starts_with('"') {
                            if let Some(end_q) = next_literal[1..].find('"') {
                                let quoted_inner = &next_literal[1..end_q+1];
                                if !quoted_inner.is_empty() && (quoted_inner.chars().next().unwrap().is_alphanumeric() || quoted_inner.chars().next().unwrap() == '_') {
                                    need_brace = true;
                                }
                            } else if next_literal.chars().next().unwrap().is_alphanumeric() || next_literal.chars().next().unwrap() == '_' {
                                need_brace = true;
                            }
                        } else if next_literal.chars().next().unwrap().is_alphanumeric() || next_literal.chars().next().unwrap() == '_' {
                            need_brace = true;
                        }
                    }
                }
                if need_brace {
                    inner_parts.push(format!("${{{}}}", var));
                } else {
                    inner_parts.push(format!("${}", var));
                }
            },
            "param_simple" => {
                let var = exp.inner.as_ref().unwrap();
                let idx = exps.iter().position(|e| e.start == exp.start).unwrap();
                let mut need_brace = false;
                if idx + 1 < exps.len() {
                    let next_exp = &exps[idx+1];
                    let next_literal = &middle[exp_end_in_middle..next_exp.start - first.start];
                    if !next_literal.is_empty() && (next_literal.chars().next().unwrap().is_alphanumeric() || next_literal.chars().next().unwrap() == '_') {
                        need_brace = true;
                    }
                }
                if need_brace {
                    inner_parts.push(format!("${{{}}}", var));
                } else {
                    inner_parts.push(format!("${}", var));
                }
            },
            "param_complex" => {
                inner_parts.push(exp.text.clone());
            },
            "array" => {
                let mut inner = exp.inner.as_ref().unwrap().clone();
                if inner.ends_with("[*]") {
                    inner = inner[..inner.len()-3].to_string() + "[@]";
                }
                inner_parts.push(format!("${{{}}}", inner));
            },
            "special" => {
                if exp.text == "$*" || exp.text == "$@" {
                    inner_parts.push("$@".to_string());
                } else {
                    inner_parts.push(exp.text.clone());
                }
            },
            "cmdsub" => {
                let inner = &exp.text[2..exp.text.len()-1];
                let transformed_inner = transform_text(inner);
                inner_parts.push(format!("$({})", transformed_inner));
            },
            "old_arith" => {
                let inner = &exp.text[2..exp.text.len()-1];
                let transformed_inner = transform_text(inner);
                inner_parts.push(format!("$[{}]", transformed_inner));
            },
            "arith" => {
                inner_parts.push(exp.text.clone());
            },
            "backtick" => {
                let inner = &exp.text[1..exp.text.len()-1];
                let transformed_inner = transform_text(inner);
                inner_parts.push(format!("$({})", transformed_inner));
            },
            _ => {
                inner_parts.push(exp.text.clone());
            }
        }
        pos = exp_end_in_middle;
    }
    let inner = inner_parts.join("");
    format!("{}\"{}\"{}", prefix, inner, suffix)
}

#[derive(Debug, Clone)]
struct Expansion {
    start: usize,
    end: usize,
    text: String,
    typ: String,
    inner: Option<String>,
}

fn find_expansions(word: &str) -> Vec<Expansion> {
    let mut exps = Vec::new();
    let chars: Vec<char> = word.chars().collect();
    let mut i = 0;
    let mut in_single = false;
    let mut in_double = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' && !in_double {
            // Find closing '
            let mut j = i+1;
            while j < chars.len() && chars[j] != '\'' {
                j += 1;
            }
            if j < chars.len() {
                i = j+1;
                continue;
            } else {
                break;
            }
        }
        if c == '"' && !in_single {
            // Find closing "
            let mut j = i+1;
            let mut escaped = false;
            while j < chars.len() {
                if chars[j] == '\\' && !escaped {
                    escaped = true;
                    j += 1;
                    continue;
                }
                if chars[j] == '"' && !escaped {
                    break;
                }
                escaped = false;
                j += 1;
            }
            if j < chars.len() {
                i = j+1;
                continue;
            } else {
                break;
            }
        }
        if c == '$' && !in_single {
            if i+1 >= chars.len() {
                i += 1;
                continue;
            }
            let nxt = chars[i+1];
            if nxt == '\'' || nxt == '"' {
                // $'...' or $"..."
                let quote = nxt;
                let mut j = i+2;
                while j < chars.len() && chars[j] != quote {
                    if chars[j] == '\\' {
                        j += 2;
                        continue;
                    }
                    j += 1;
                }
                if j < chars.len() {
                    i = j+1;
                    continue;
                } else {
                    i += 1;
                    continue;
                }
            }
            if nxt == '(' {
                if i+2 < chars.len() && chars[i+2] == '(' {
                    // $(( 
                    let mut j = i+3;
                    let mut depth = 1;
                    while j +1 < chars.len() {
                        if chars[j] == '(' && chars[j+1] == '(' {
                            depth += 1;
                            j += 2;
                            continue;
                        }
                        if chars[j] == ')' && chars[j+1] == ')' {
                            depth -= 1;
                            if depth == 0 {
                                j += 2;
                                break;
                            }
                            j += 2;
                            continue;
                        }
                        j += 1;
                    }
                    if j <= chars.len() {
                        let text = word[i..j].to_string();
                        exps.push(Expansion { start: i, end: j, text, typ: "arith".to_string(), inner: None });
                        i = j;
                        continue;
                    } else {
                        i += 1;
                        continue;
                    }
                } else {
                    // $(...)
                    let mut depth = 1;
                    let mut j = i+2;
                    while j < chars.len() && depth > 0 {
                        if chars[j] == '(' {
                            depth += 1;
                        } else if chars[j] == ')' {
                            depth -= 1;
                            if depth == 0 {
                                j += 1;
                                break;
                            }
                        }
                        j += 1;
                    }
                    let text = word[i..j].to_string();
                    exps.push(Expansion { start: i, end: j, text, typ: "cmdsub".to_string(), inner: None });
                    i = j;
                    continue;
                }
            }
            if nxt == '{' {
                // Find matching }
                let mut depth = 0;
                let mut j = i+1;
                while j < chars.len() {
                    if chars[j] == '{' {
                        depth += 1;
                    } else if chars[j] == '}' {
                        depth -= 1;
                        if depth == 0 {
                            j += 1;
                            break;
                        }
                    }
                    j += 1;
                }
                let text = word[i..j].to_string();
                let inner = if j > i+2 { word[i+2..j-1].to_string() } else { String::new() };
                let typ = if inner.starts_with('#') || inner.starts_with('!') {
                    "special"
                } else if inner.ends_with("[@]") || inner.ends_with("[*]") {
                    "array"
                } else if inner.chars().all(|c| c.is_alphanumeric() || c == '_') && !inner.is_empty() && (inner.chars().next().unwrap().is_alphabetic() || inner.chars().next().unwrap() == '_') {
                    "param_simple"
                } else {
                    "param_complex"
                }.to_string();
                exps.push(Expansion { start: i, end: j, text, typ, inner: Some(inner) });
                i = j;
                continue;
            }
            if nxt == '[' {
                // $[
                let mut j = i+2;
                while j < chars.len() && chars[j] != ']' {
                    j += 1;
                }
                if j < chars.len() {
                    j += 1;
                    let text = word[i..j].to_string();
                    exps.push(Expansion { start: i, end: j, text, typ: "old_arith".to_string(), inner: None });
                    i = j;
                    continue;
                } else {
                    i += 1;
                    continue;
                }
            }
            if nxt == '$' || nxt == '?' || nxt == '!' || nxt == '#' || nxt == '*' || nxt == '@' {
                let text = word[i..i+2].to_string();
                exps.push(Expansion { start: i, end: i+2, text, typ: "special".to_string(), inner: None });
                i += 2;
                continue;
            }
            if nxt.is_ascii_digit() {
                let text = word[i..i+2].to_string();
                exps.push(Expansion { start: i, end: i+2, text, typ: "positional".to_string(), inner: None });
                i += 2;
                continue;
            }
            if is_var_start(nxt) {
                let mut j = i+1;
                while j < chars.len() && is_var_char(chars[j]) {
                    j += 1;
                }
                let text = word[i..j].to_string();
                exps.push(Expansion { start: i, end: j, text, typ: "var".to_string(), inner: None });
                i = j;
                continue;
            }
            i += 1;
            continue;
        }
        if c == '`' && !in_single && !in_double {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' {
                j += 1;
            }
            if j < chars.len() {
                let text = word[i..j+1].to_string();
                exps.push(Expansion { start: i, end: j+1, text, typ: "backtick".to_string(), inner: None });
                i = j+1;
                continue;
            } else {
                i += 1;
                continue;
            }
        }
        i += 1;
    }
    exps
}

fn tokenize(code: &str) -> Vec<(String, String)> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = code.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() {
            let mut j = i+1;
            while j < chars.len() && chars[j].is_whitespace() {
                j += 1;
            }
            tokens.push(("space".to_string(), code[i..j].to_string()));
            i = j;
            continue;
        }
        if c == '#' {
            // Should be handled as comment, but if here, treat as rest
            tokens.push(("other".to_string(), code[i..].to_string()));
            break;
        }
        // Multi-char operators
        if i+1 < chars.len() {
            let two = &code[i..i+2];
            if two == "&&" || two == "||" || two == ";;" || two == "<<" || two == ">>" {
                if i+2 < chars.len() && &code[i..i+3] == "<<<" {
                    tokens.push(("op".to_string(), "<<<".to_string()));
                    i += 3;
                    continue;
                }
                if i+2 < chars.len() && &code[i..i+3] == "<<-" {
                    tokens.push(("op".to_string(), "<<-".to_string()));
                    i += 3;
                    continue;
                }
                tokens.push(("op".to_string(), two.to_string()));
                i += 2;
                continue;
            }
        }
        if c == ';' || c == '&' || c == '|' || c == '<' || c == '>' || c == '(' || c == ')' || c == '{' || c == '}' {
            // Handle [[, ((, etc.
            if i+1 < chars.len() && c == '[' && chars[i+1] == '[' {
                tokens.push(("op".to_string(), "[[".to_string()));
                i += 2;
                continue;
            }
            if i+1 < chars.len() && c == ']' && chars[i+1] == ']' {
                tokens.push(("op".to_string(), "]]".to_string()));
                i += 2;
                continue;
            }
            if i+1 < chars.len() && c == '(' && chars[i+1] == '(' {
                tokens.push(("op".to_string(), "((".to_string()));
                i += 2;
                continue;
            }
            if i+1 < chars.len() && c == ')' && chars[i+1] == ')' {
                tokens.push(("op".to_string(), "))".to_string()));
                i += 2;
                continue;
            }
            tokens.push(("op".to_string(), c.to_string()));
            i += 1;
            continue;
        }
        // Word
        let mut j = i;
        let mut in_single = false;
        let mut in_double = false;
        while j < chars.len() {
            let ch = chars[j];
            if ch == '\'' && !in_double {
                let mut k = j+1;
                while k < chars.len() && chars[k] != '\'' {
                    k += 1;
                }
                if k < chars.len() {
                    j = k+1;
                    continue;
                } else {
                    j = chars.len();
                    break;
                }
            }
            if ch == '"' && !in_single {
                let mut k = j+1;
                let mut escaped = false;
                while k < chars.len() {
                    if chars[k] == '\\' && !escaped {
                        escaped = true;
                        k += 1;
                        continue;
                    }
                    if chars[k] == '"' && !escaped {
                        break;
                    }
                    escaped = false;
                    k += 1;
                }
                if k < chars.len() {
                    j = k+1;
                    continue;
                } else {
                    j = chars.len();
                    break;
                }
            }
            if ch.is_whitespace() || ch == ';' || ch == '&' || ch == '|' || ch == '<' || ch == '>' || ch == '(' || ch == ')' || ch == '{' || ch == '}' {
                break;
            }
            if ch == '$' {
                // Include expansion
                if j+1 < chars.len() {
                    let nxt = chars[j+1];
                    if nxt == '{' {
                        let mut depth = 0;
                        let mut k = j+1;
                        while k < chars.len() {
                            if chars[k] == '{' {
                                depth += 1;
                            } else if chars[k] == '}' {
                                depth -= 1;
                                if depth == 0 {
                                    k += 1;
                                    break;
                                }
                            }
                            k += 1;
                        }
                        j = k;
                        continue;
                    } else if nxt == '(' {
                        if j+2 < chars.len() && chars[j+2] == '(' {
                            let mut k = j+3;
                            let mut depth = 1;
                            while k+1 < chars.len() {
                                if chars[k] == '(' && chars[k+1] == '(' {
                                    depth += 1;
                                    k += 2;
                                    continue;
                                }
                                if chars[k] == ')' && chars[k+1] == ')' {
                                    depth -= 1;
                                    if depth == 0 {
                                        k += 2;
                                        break;
                                    }
                                    k += 2;
                                    continue;
                                }
                                k += 1;
                            }
                            j = k;
                            continue;
                        } else {
                            let mut depth = 1;
                            let mut k = j+2;
                            while k < chars.len() && depth > 0 {
                                if chars[k] == '(' {
                                    depth += 1;
                                } else if chars[k] == ')' {
                                    depth -= 1;
                                    if depth == 0 {
                                        k += 1;
                                        break;
                                    }
                                }
                                k += 1;
                            }
                            j = k;
                            continue;
                        }
                    } else if nxt == '[' {
                        let mut k = j+2;
                        while k < chars.len() && chars[k] != ']' {
                            k += 1;
                        }
                        if k < chars.len() {
                            k += 1;
                        }
                        j = k;
                        continue;
                    } else if nxt == '$' || nxt == '?' || nxt == '!' || nxt == '#' || nxt == '*' || nxt == '@' || nxt.is_ascii_digit() || is_var_start(nxt) {
                        j += 1;
                        if is_var_start(nxt) {
                            j += 1;
                            while j < chars.len() && is_var_char(chars[j]) {
                                j += 1;
                            }
                        } else {
                            j += 1;
                        }
                        continue;
                    }
                }
            }
            if ch == '`' {
                let mut k = j+1;
                while k < chars.len() && chars[k] != '`' {
                    k += 1;
                }
                if k < chars.len() {
                    j = k+1;
                    continue;
                } else {
                    j += 1;
                    continue;
                }
            }
            j += 1;
        }
        tokens.push(("word".to_string(), code[i..j].to_string()));
        i = j;
    }
    tokens
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let (help_version_seq, mode, files, unknown_opt) = parse_args(&args);
    if let Some(unk) = unknown_opt {
        for hv in &help_version_seq {
            if hv == "help" {
                print!("{}", HELP_TEXT);
            } else if hv == "version" {
                println!("{}", VERSION);
            }
