fn syntax_highlight(text: &str) -> String {
    // Simple syntax highlighting for basic cases
    // For now, we will implement highlighting for:
    // - keywords: if, then, fi, for, in, do, done, case, esac, select, while, etc. as bold
    // - builtins: echo, true, etc. as magenta 192,0,128
    // - variables: $var as blue 63,127,207
    // - strings: double quoted as red, single as yellow, $' as orange
    // - comments as green italic
    // For simplicity, we will handle only a few
    // We'll do a simple replacement for echo and $var
    let mut out = String::new();
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    for line in lines {
        // Check if comment
        if line.trim_start().starts_with('#') {
            out.push_str("\x1b[0;1;3;38;2;120;144;96m");
            out.push_str(line.trim_end_matches(|c| c == '\n' || c == '\r'));
            out.push_str("\x1b[m");
            if line.ends_with('\n') {
                out.push('\n');
            }
            continue;
        }
        // For other, we will highlight
        // Find $var and wrap
        let mut highlighted = String::new();
        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();
        while i < chars.len() {
            // Check for echo
            if line[i..].starts_with("echo") && (i==0 || chars[i-1].is_whitespace()) && (i+4 >= chars.len() || chars[i+4].is_whitespace() || chars[i+4] == ';' || chars[i+4] == '\n') {
                highlighted.push_str("\x1b[0;38;2;192;0;128mecho\x1b[m");
                i += 4;
                continue;
            }
            // Check for $var
            if chars[i] == '$' && i+1 < chars.len() {
                let nxt = chars[i+1];
                if nxt == '?' || nxt == '$' || nxt == '!' || nxt == '#' || nxt == '*' || nxt == '@' {
                    highlighted.push_str("\x1b[0;38;2;63;127;207m");
                    highlighted.push('$');
                    highlighted.push(nxt);
                    highlighted.push_str("\x1b[m");
                    i += 2;
                    continue;
                }
                if nxt.is_ascii_digit() {
                    highlighted.push_str("\x1b[0;38;2;63;127;207m");
                    highlighted.push('$');
                    highlighted.push(nxt);
                    highlighted.push_str("\x1b[m");
                    i += 2;
                    continue;
                }
                if nxt == '{' {
                    // Find }
                    let mut j = i+2;
                    while j < chars.len() && chars[j] != '}' {
                        j += 1;
                    }
                    if j < chars.len() {
                        highlighted.push_str("\x1b[0;38;2;63;127;207m");
                        highlighted.push_str(&line[i..j+1]);
                        highlighted.push_str("\x1b[m");
                        i = j+1;
                        continue;
                    }
                }
                if nxt.is_alphabetic() || nxt == '_' {
                    let mut j = i+1;
                    while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') {
                        j += 1;
                    }
                    highlighted.push_str("\x1b[0;38;2;63;127;207m");
                    highlighted.push_str(&line[i..j]);
                    highlighted.push_str("\x1b[m");
                    i = j;
                    continue;
                }
                if nxt == '(' {
                    // $( or $((
                    if i+2 < chars.len() && chars[i+2] == '(' {
                        // $(( 
                        let mut j = i+3;
                        while j+1 < chars.len() && !(chars[j] == ')' && chars[j+1] == ')') {
                            j += 1;
                        }
                        if j+1 < chars.len() {
                            highlighted.push_str("\x1b[0;38;2;192;0;192m$(( ");
                            // Not handling inner, just push
                            highlighted.push_str(&line[i+3..j]);
                            highlighted.push_str("))\x1b[m");
                            i = j+2;
                            continue;
                        }
                    } else {
                        // $( 
                        let mut depth = 1;
                        let mut j = i+2;
                        while j < chars.len() && depth > 0 {
                            if chars[j] == '(' {
                                depth += 1;
                            } else if chars[j] == ')' {
                                depth -= 1;
                                if depth == 0 {
                                    j += 1;
                                    break;
                                }
                            }
                            j += 1;
                        }
                        highlighted.push_str("\x1b[0;38;2;192;0;128m$(");
                        highlighted.push_str(&line[i+2..j-1]);
                        highlighted.push_str(")\x1b[m");
                        i = j;
                        continue;
                    }
                }
            }
            // Check for double quoted string
            if chars[i] == '"' {
                let mut j = i+1;
                while j < chars.len() && chars[j] != '"' {
                    if chars[j] == '\\' {
                        j += 2;
                        continue;
                    }
                    j += 1;
                }
                if j < chars.len() {
                    highlighted.push_str("\x1b[0;38;2;255;0;0m\"");
                    // Inside, highlight $var
                    let inner = &line[i+1..j];
                    // Find $var inside
                    let mut k = 0;
                    let inner_chars: Vec<char> = inner.chars().collect();
                    while k < inner_chars.len() {
                        if inner_chars[k] == '$' && k+1 < inner_chars.len() {
                            let nxt2 = inner_chars[k+1];
                            if nxt2.is_alphabetic() || nxt2 == '_' {
                                let mut l = k+1;
                                while l < inner_chars.len() && (inner_chars[l].is_alphanumeric() || inner_chars[l] == '_') {
                                    l += 1;
                                }
                                highlighted.push_str("\x1b[0;38;2;63;127;207m");
                                highlighted.push_str(&inner[k..l]);
                                highlighted.push_str("\x1b[0;38;2;255;0;0m");
                                k = l;
                                continue;
                            }
                        }
                        highlighted.push(inner_chars[k]);
                        k += 1;
                    }
                    highlighted.push_str("\"\x1b[m");
                    i = j+1;
                    continue;
                }
            }
            if chars[i] == '\'' {
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' {
                    j += 1;
                }
                if j < chars.len() {
                    highlighted.push_str("\x1b[0;38;2;255;204;85m");
                    highlighted.push_str(&line[i..j+1]);
                    highlighted.push_str("\x1b[m");
                    i = j+1;
                    continue;
                }
            }
            highlighted.push(chars[i]);
            i += 1;
        }
        out.push_str(&highlighted);
    }
    out
}

fn syntax_suggest_highlight(original: &str, transformed: &str) -> String {
